SELECT COUNT(*) FROM users as u, comments as c, posts as p, postHistory as ph, badges as b WHERE c.UserId = u.Id AND b.UserId = u.Id AND p.Id = c.PostId AND p.Id = ph.PostId AND c.Score=0 AND c.CreationDate>='2010-07-26 17:09:48'::timestamp AND p.PostTypeId=1 AND p.AnswerCount>=0 AND p.CommentCount>=0 AND p.CommentCount<=14 AND ph.CreationDate<='2014-09-11 20:09:41'::timestamp;